mode = (sys.argv[1] if len(sys.argv) > 1 else "dry").strip()
assert mode in ("dry", "apply")
actor = Actor(id=UUID(int=0), name="Температура усадки по паспортам 16.11.2026", department="System")
factory = build_references_uow_factory(build_engine(os.environ["ERP_DATABASE_URL"]))
with factory() as uow:
    recs = {str(r.id): r for r in uow.tech_operations.list(tab=TechOperationTab.HEAT_SHRINK, query="", limit=100_000)}
todo = done = conflict = missing = failed = 0
for c in CELLS:
    rec = recs.get(c["id"])
    if rec is None:
        missing += 1; print("  нет строки", c["id"]); continue
    cur = {k: str(rec.fields.get(k) or "") for k in c["fields"]}
    edits = tuple(FieldEdit(k, cur[k], v) for k, v in c["fields"].items() if cur[k] != v)
    if not edits:
        done += 1; continue
    if any(e.old for e in edits):
        conflict += 1; print("  занято", c["id"], [(e.field, e.old, e.value) for e in edits if e.old]); continue
    todo += 1
    if mode == "apply":
        try:
            edit_record(EditRecordCommand(rec.id, edits, actor, moscow_now()), factory())
        except Exception as error:
            failed += 1; print("  ошибка", c["id"], error)
print("mode", mode, "к записи", todo, "уже записано", done, "занято", conflict, "нет строки", missing, "ошибок", failed)
